"""Batched campaign: one planner process per worker block."""
import json, sys, time
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0, '/app/work')

KINDS = ["rand", "feas", "tight", "exact", "maxsize", "long"]

def make(kind, seed):
    import gen as G, gen2 as G2, maxsize as MS, longpath as LP
    if kind == "rand": return G.gen(seed)
    if kind == "feas": return G2.gen(seed, budget_mode="auto")
    if kind == "tight": return G2.gen(seed, budget_mode="huge", tight=1.0)
    if kind == "exact": return G2.gen(seed, budget_mode="exact", tight=1.05)
    if kind == "maxsize": return MS.gen(seed)
    if kind == "long": return LP.gen(seed)
    raise ValueError(kind)

def worker(task):
    kind, seeds, prog = task
    import subprocess, check as C
    reqs = [make(kind, s) for s in seeds]
    data = "".join(json.dumps(r) + "\n" for r in reqs).encode()
    p = subprocess.run([sys.executable, prog], input=data, capture_output=True,
                       timeout=900)
    if p.returncode != 0:
        return [(seeds[0], kind, "CRASH rc=%d %s" % (p.returncode, p.stderr.decode()[-400:],), "")]
    out = p.stdout.decode().splitlines()
    res = []
    if len(out) != len(reqs):
        return [(seeds[0], kind, "LINE COUNT %d vs %d" % (len(out), len(reqs)), "")]
    for s, r, line in zip(seeds, reqs, out):
        try:
            resp = json.loads(line)
        except Exception:
            res.append((s, kind, "UNPARSEABLE " + line[:200], "")); continue
        L = C.build(r)
        try:
            st, val = C.check_response(r, resp, L)
            res.append((s, kind, None, st))
        except Exception as e:
            res.append((s, kind, repr(e), json.dumps(resp)[:300] + " || " + json.dumps(r)[:300]))
    return res

def main():
    n = int(sys.argv[1]); seed0 = int(sys.argv[2])
    block = int(sys.argv[3]) if len(sys.argv) > 3 else 20
    prog = sys.argv[4] if len(sys.argv) > 4 else '/app/submission/planner.py'
    tasks = []
    i = 0
    while i < n:
        k = KINDS[(i // block) % len(KINDS)]
        tasks.append((k, [seed0 + i + j for j in range(min(block, n - i))], prog))
        i += block
    t0 = time.time()
    from collections import Counter
    c = Counter(); bad = 0
    with ThreadPoolExecutor(max_workers=4) as pool:
        for group in pool.map(worker, tasks):
            for seed, kind, err, info in group:
                if err:
                    bad += 1
                    print("FAIL", kind, seed, err)
                    print("    ", info[:700])
                else:
                    c[(kind, info)] += 1
    print("done %d in %.1fs bad %d" % (n, time.time() - t0, bad))
    for k in sorted(c): print("   ", k, c[k])
    return 1 if bad else 0

sys.exit(main())
PYEOF
